from pathlib import Path
out=Path(__file__).resolve().parents[1]/'src/assets'
def save(name,body):
 defs='''<defs><linearGradient id="top" x2=".8" y2="1"><stop stop-color="#e8f8ff"/><stop offset="1" stop-color="#72c7ff"/></linearGradient><linearGradient id="side" x2="1" y2="1"><stop stop-color="#8bd5ff"/><stop offset="1" stop-color="#359fe5"/></linearGradient><linearGradient id="lav" x2="1" y2="1"><stop stop-color="#eee6ff"/><stop offset=".5" stop-color="#c9b5ff"/><stop offset="1" stop-color="#9879dc"/></linearGradient><linearGradient id="cream" x2=".8" y2="1"><stop stop-color="#fff9d2"/><stop offset="1" stop-color="#ffe45c"/></linearGradient><radialGradient id="sphere" cx=".3" cy=".2" r=".85"><stop stop-color="#fffdf1"/><stop offset=".45" stop-color="#ffc0a4"/><stop offset="1" stop-color="#ff9278"/></radialGradient><linearGradient id="dark" x2="1" y2="1"><stop stop-color="#53627f"/><stop offset="1" stop-color="#17243d"/></linearGradient><filter id="shadow" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="12"/></filter><filter id="object" x="-40%" y="-40%" width="180%" height="190%"><feDropShadow dx="0" dy="16" stdDeviation="10" flood-color="#6b7698" flood-opacity=".16"/></filter></defs>'''
 out.joinpath(name+'.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 360">'+defs+'<ellipse cx="245" cy="305" rx="118" ry="17" fill="#7787a4" opacity=".17" filter="url(#shadow)"/>'+body+'</svg>')
def cube(x,y,w=84,color='top'):
 return f'<g filter="url(#object)"><path d="M{x} {y}l{w} -{w/2} {w} {w/2} -{w} {w/2}Z" fill="url(#{color})"/><path d="M{x} {y}v{w}l{w} {w/2}v-{w}Z" fill="url(#side)"/><path d="M{x+w} {y+w/2}l{w} -{w/2}v{w}l-{w} {w/2}Z" fill="url(#lav)"/></g>'
book='''<g filter="url(#object)"><path d="M103 207 268 117 385 178 220 270Z" fill="url(#side)"/><path d="M103 207v22l117 63v-22Z" fill="#80b1e7"/><path d="m220 270 165-92v22l-165 92Z" fill="#b9a3f0"/><path d="M111 194 268 110 377 167 220 253Z" fill="url(#cream)"/><path d="M111 194v16l109 59v-16Z" fill="#e4dfd5"/><path d="m220 253 157-86v16l-157 86Z" fill="#fffdf7"/><path d="M102 187 267 96 386 159 220 251Z" fill="url(#lav)"/><path d="m129 179 138-75 20 11-138 75Z" fill="#ffffff" opacity=".55"/><path d="m216 183 62-34 45 24-62 34Z" fill="#f7f4fd" opacity=".75"/></g><g filter="url(#object)"><path d="m259 47 84 26-14 97-84-27Z" fill="#fcfdff"/><path d="m275 78 43 14m-47 1 43 14m-47 1 31 10" fill="none" stroke="#76b5de" stroke-width="4" stroke-linecap="round"/></g><circle cx="124" cy="93" r="19" fill="url(#sphere)"/>'''
save('literature',book)
