save('modules',cube(114,192,64)+cube(220,111,76,'lav')+'''<path d="m181 195 47-34" stroke="#cbd6e8" stroke-width="13" stroke-linecap="round"/><circle cx="358" cy="214" r="34" fill="url(#sphere)" filter="url(#object)"/><circle cx="130" cy="89" r="18" fill="url(#lav)"/>''')
