save('signal','''<g filter="url(#object)" transform="rotate(-15 245 172)"><path d="m172 170 119-71v152l-119-39Z" fill="url(#cream)"/><ellipse cx="291" cy="175" rx="43" ry="76" fill="url(#lav)"/><ellipse cx="292" cy="173" rx="29" ry="56" fill="#a181e4"/><ellipse cx="296" cy="170" rx="16" ry="37" fill="url(#cream)"/><path d="m181 199 30 11-9 73-23-8Z" fill="url(#side)"/><rect x="149" y="167" width="43" height="49" rx="17" fill="url(#top)"/></g><path d="M365 116q26 38 5 77m18-91q36 51 9 105" fill="none" stroke="#c3d2e8" stroke-width="7" stroke-linecap="round"/>''')
