save('compass','''<g filter="url(#object)"><ellipse cx="243" cy="200" rx="123" ry="83" fill="url(#side)"/><ellipse cx="243" cy="185" rx="123" ry="83" fill="url(#top)"/><ellipse cx="243" cy="185" rx="102" ry="65" fill="url(#cream)"/><ellipse cx="243" cy="185" rx="89" ry="54" fill="#f9faff"/><path d="m288 119-25 77-65 56 25-77Z" fill="url(#dark)"/><path d="m288 119-25 77-20-11Z" fill="#9cafcf"/><path d="m198 252 25-77 20 10Z" fill="url(#lav)"/><circle cx="243" cy="185" r="11" fill="url(#sphere)"/></g><circle cx="112" cy="87" r="24" fill="url(#lav)"/><circle cx="375" cy="113" r="17" fill="url(#sphere)"/>''')
print('7 local dimensional SVG assets generated')
